<?php require '../config/config.php'; require_admin(); if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM events WHERE id=?')->execute([(int)$_GET['delete']]);header('Location: events.php');exit;} if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('INSERT INTO events(title,event_date,start_time,end_time,location,description) VALUES(?,?,?,?,?,?)')->execute([$_POST['title'],$_POST['event_date'],$_POST['start_time']?:null,$_POST['end_time']?:null,$_POST['location'],$_POST['description']]);flash('success','Event added.');header('Location: events.php');exit;} $rows=$pdo->query('SELECT * FROM events ORDER BY event_date')->fetchAll(); $title='Manage Events'; require '../includes/header.php'; ?><div class="adminnav"><div class="container"><a href="index.php">Dashboard</a><a href="members.php">Members</a><a href="online-users.php">Online Users</a><a href="administrators.php">Administrators</a><a href="reports.php">Reports</a><a href="support.php">Support Requests</a><a href="donations.php">Donations</a><a href="events.php">Events</a><a href="news.php">News</a><a href="messages.php">Messages</a></div></div><section class="section"><div class="container"><h1>Manage Events</h1><div class="formwrap" style="margin:20px 0"><form method="post"><div class="field"><label>Title</label><input name="title" required></div><div class="formgrid"><div class="field"><label>Date</label><input type="date" name="event_date" required></div><div class="field"><label>Location</label><input name="location"></div><div class="field"><label>Start</label><input type="time" name="start_time"></div><div class="field"><label>End</label><input type="time" name="end_time"></div></div><div class="field"><label>Description</label><textarea name="description"></textarea></div><button class="btn">Add Event</button></form></div><table class="table"><tr><th>Event</th><th>Date</th><th>Location</th><th></th></tr><?php foreach($rows as $r): ?><tr><td><?=e($r['title'])?></td><td><?=e($r['event_date'])?></td><td><?=e($r['location'])?></td><td><a class="date" data-confirm="Delete this event?" href="?delete=<?=$r['id']?>">Delete</a></td></tr><?php endforeach; ?></table></div></section><?php require '../includes/footer.php'; ?>
